window.RP_SESSION={"id":"S-5b3f643feaef","messages":[{"id":"Plane-0000954","time":"2026-09-21T03:19:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"여기서 요리하는건 처음 같은디.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000955","time":"2026-09-21T03:19:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 고기를 한 점 굽고 있다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000956","time":"2026-09-21T03:19:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"큰거 하나 사려고 돈 아끼는 중인데 고기는 먹고 싶어!","characters":["P-fec1db60d51e"]},{"id":"Plane-0000957","time":"2026-09-21T03:20:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래서 떠올린 아이디어.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000958","time":"2026-09-21T03:22:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잘 구운 고기 하나.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000959","time":"2026-09-21T03:22:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"보섭살... 은 아니고, 그냥 사온 소고기를 소금으로 간한다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000960","time":"2026-09-21T03:23:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"소금의 힘으로 물기가 빠질 때 까지 기다렸다가, 깨끗한 천으로 살살 닦아내고.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000961","time":"2026-09-21T03:24:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"불 위에 얹은 프라이팬에 소량의 기름을 두르고, 손등을 가까이 가져다 댔을 때 닿으면 안되겠다 싶은 온도까지 올린다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000962","time":"2026-09-21T03:25:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마가 소고기를 프라이팬 위에 얹자 치이익... 하고 비 오는 소리와 함께 고소한 마이야르의 향기가 부엌 가득 퍼져나간다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000963","time":"2026-09-21T03:25:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"겉을 먼저 빠르게 지지고, 숯을 조금 앞뒤로 빼서 약한 불을 만들어 시간을 들여 굽는다...","characters":["P-fec1db60d51e"]},{"id":"Plane-0000964","time":"2026-09-21T03:27:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"지글지글","characters":["P-fec1db60d51e"]},{"id":"Plane-0000965","time":"2026-09-21T03:27:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"작은 바늘 같은 것으로 고기를 찔러보고, 그 끝을 다시 입술에 가져다대서 고기의 심부 온도를 체크한다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000966","time":"2026-09-21T03:29:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"체온 수준, 그보다 좀 더 높은 온도가 되었을 때, 불을 불씨로 정리하고, 팬에서 고기를 꺼내 접시에 담는다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000967","time":"2026-09-21T03:29:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-fec1db60d51e"]},{"id":"Plane-0000968","time":"2026-09-21T03:29:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"포크랑 나이프 설거지 하기 귀찮은데.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000969","time":"2026-09-21T03:30:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 접시에 담긴 고기를 손으로 쥐고 뜯어먹는다. 부드럽게 구워진 고기는 그냥 이빨로도 잘 잘린다.","characters":["P-fec1db60d51e"]},{"id":"Plane-0000970","time":"2026-09-21T03:30:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"지나가는 누가 보고 티평이라고 하겠지만...","characters":["P-fec1db60d51e"]},{"id":"Plane-0000971","time":"2026-09-21T03:30:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맛있어!","characters":["P-fec1db60d51e"]},{"id":"Plane-0000972","time":"2026-09-21T03:45:00+09:00","room":"Plane","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]}]};
